import React, { useEffect, useMemo, useState } from "react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { useAuth } from "@/_core/hooks/useAuth";
import { trpc } from "@/lib/trpc";
import { AlertTriangle, Building2, Database, FileText, FlaskConical, GitCompareArrows, Plus, RefreshCw, ShieldCheck } from "lucide-react";

const studyStatusLabel = (status: string) => status === "DRAFT" ? "Rascunho" : status === "ACTIVE" ? "Activo" : "Arquivado";
const versionStatusLabel = (status: string) => status === "APPROVED" ? "Aprovada" : status === "IN_REVIEW" ? "Em revisão" : status === "ARCHIVED" ? "Arquivada" : "Rascunho";
const snapshotStatusLabel = (status: string) => status === "READY" ? "Pronto" : status === "STALE" ? "Desactualizado" : "Inválido";
const workflowStatusLabel = (status: string) => ({ RASCUNHO: "Rascunho", EM_ANALISE: "Em análise", AGUARDANDO_VALIDACAO: "Aguardando validação", VALIDADO: "Validado", CONCLUIDO: "Concluído", ARQUIVADO: "Arquivado" } as Record<string, string>)[status] ?? status;
const companyDisplayName = (name: string) => name.replace(/BALANCERTS Test Tenant - Disposable/gi, "BALANCERTS — Empresa de teste").replace(/tenant/gi, "organização").replace(/disposable/gi, "teste");

export default function Saadi() {
  const { user } = useAuth();
  const companies = trpc.companies.list.useQuery();
  const rows = [...(companies.data ?? [])].sort((left, right) => (left.company.name.toLowerCase().includes("repair lubatec") ? -1 : right.company.name.toLowerCase().includes("repair lubatec") ? 1 : 0));
  const [companyId, setCompanyId] = useState<number | undefined>();
  const [studyId, setStudyId] = useState<number | undefined>();
  const [code, setCode] = useState("");
  const [name, setName] = useState("");
  const [investmentDomain, setInvestmentDomain] = useState<"IMOBILIARIO" | "AGRICULTURA" | "INDUSTRIA" | "ENERGIA" | "HOTELARIA" | "LOGISTICA" | "OUTRO">("OUTRO");
  const [studyEntityType, setStudyEntityType] = useState<"ERP" | "EXTERNA">("ERP");
  const [studyType, setStudyType] = useState("INVESTIMENTO");
  const [studyDescription, setStudyDescription] = useState("");
  const [projectionHorizonYears, setProjectionHorizonYears] = useState("5");
  const [externalLegalName, setExternalLegalName] = useState("");
  const [externalNif, setExternalNif] = useState("");
  const [externalActivity, setExternalActivity] = useState("");
  const [externalProvince, setExternalProvince] = useState("");
  const [externalMunicipality, setExternalMunicipality] = useState("");
  const [externalAddress, setExternalAddress] = useState("");
  const [externalEmail, setExternalEmail] = useState("");
  const [documentFilename, setDocumentFilename] = useState("");
  const [documentStorageKey, setDocumentStorageKey] = useState("");
  const [documentCategory, setDocumentCategory] = useState("BALANCO");
  const [documentMimeType, setDocumentMimeType] = useState("application/pdf");
  const [documentSize, setDocumentSize] = useState("1");
  const [nextWorkflowStatus, setNextWorkflowStatus] = useState<"RASCUNHO" | "EM_ANALISE" | "AGUARDANDO_VALIDACAO" | "VALIDADO" | "CONCLUIDO" | "ARQUIVADO">("EM_ANALISE");
  const [assumptionName, setAssumptionName] = useState("");
  const [assumptionValue, setAssumptionValue] = useState("");
  const [assumptionUnit, setAssumptionUnit] = useState("AOA");
  const [assumptionStartYear, setAssumptionStartYear] = useState(String(new Date().getFullYear()));
  const [assumptionEndYear, setAssumptionEndYear] = useState(String(new Date().getFullYear() + 5));
  const [assumptionSource, setAssumptionSource] = useState("");
  const [assumptionNotes, setAssumptionNotes] = useState("");
  const selected = rows.find(({ company }) => company.id === companyId) ?? rows[0];
  const activeCompanyId = selected?.company.id;
  const organizationId = selected?.company.organizationId;
  const studies = trpc.saadi.studies.useQuery(
    activeCompanyId && organizationId ? { companyId: activeCompanyId, organizationId } : { companyId: 0, organizationId: 0 },
    { enabled: Boolean(activeCompanyId && organizationId) },
  );
  const selectedStudyId = studyId ?? studies.data?.[0]?.id;
  const snapshots = trpc.saadi.snapshots.useQuery(
    activeCompanyId && organizationId ? { companyId: activeCompanyId, organizationId, studyId: selectedStudyId } : { companyId: 0, organizationId: 0, studyId: 0 },
    { enabled: Boolean(activeCompanyId && organizationId) },
  );
  const versions = trpc.saadi.versions.useQuery(
    activeCompanyId && organizationId && selectedStudyId ? { companyId: activeCompanyId, organizationId, studyId: selectedStudyId } : { companyId: 0, organizationId: 0, studyId: 0 },
    { enabled: Boolean(activeCompanyId && organizationId && selectedStudyId) },
  );
  const [snapshotId, setSnapshotId] = useState<number | undefined>();
  const selectedSnapshotId = snapshotId ?? snapshots.data?.[0]?.id;
  useEffect(() => {
    if (!snapshots.data?.some((snapshot) => snapshot.id === snapshotId)) setSnapshotId(snapshots.data?.[0]?.id);
  }, [snapshotId, snapshots.data]);
  const [periodId, setPeriodId] = useState("1");
  const [varianceMetric, setVarianceMetric] = useState("resultadoLiquidoRealizado");
  const [projectedValue, setProjectedValue] = useState("0");
  const [riskTitle, setRiskTitle] = useState("");
  const [riskDescription, setRiskDescription] = useState("");
  const [riskProbability, setRiskProbability] = useState("3");
  const [riskImpact, setRiskImpact] = useState("3");
  const [riskResponse, setRiskResponse] = useState<"EVITAR" | "REDUZIR" | "TRANSFERIR" | "ACEITAR">("REDUZIR");
  const [decisionChoice, setDecisionChoice] = useState<"APROVAR" | "REJEITAR" | "PEDIR_REVISAO">("APROVAR");
  const [decisionJustification, setDecisionJustification] = useState("");
  const feasibility = trpc.saadi.feasibility.useQuery(activeCompanyId && organizationId && selectedStudyId ? { organizationId, companyId: activeCompanyId, studyId: selectedStudyId } : { organizationId: 0, companyId: 0, studyId: 0 }, { enabled: Boolean(activeCompanyId && organizationId && selectedStudyId) });
  const pgcNormativeContext = trpc.saadi.erpPgcNormativeContext.useQuery({ companyId: activeCompanyId ?? 0 }, { enabled: Boolean(activeCompanyId) });
  const [initialInvestment, setInitialInvestment] = useState("1000000");
  const [discountRate, setDiscountRate] = useState("0.15");
  const [terminalGrowthRate, setTerminalGrowthRate] = useState("0.03");
  const [cashFlows, setCashFlows] = useState("300000,350000,400000,450000,500000");
  const [equityAmount, setEquityAmount] = useState("1000000");
  const [debtAmount, setDebtAmount] = useState("0");
  const [debtInterestRate, setDebtInterestRate] = useState("0.12");
  const [debtTermMonths, setDebtTermMonths] = useState("60");
  const [scenarioName, setScenarioName] = useState("Cenário base");
  const saveFeasibility = trpc.saadi.saveFeasibilityInput.useMutation({ onSuccess: async () => { await feasibility.refetch(); } });
  const calculateFeasibility = trpc.saadi.calculateFeasibility.useMutation({ onSuccess: async () => { await feasibility.refetch(); } });
  const sensitivityInput = useMemo(() => ({ initialInvestment: Number(initialInvestment) || 1, discountRate: Number(discountRate) || 0, cashFlows: cashFlows.split(",").map((value) => Number(value.trim())).filter(Number.isFinite) }), [initialInvestment, discountRate, cashFlows]);
  const sensitivity = trpc.saadi.sensitivity.useQuery(sensitivityInput, { enabled: Boolean(selectedStudyId && sensitivityInput.cashFlows.length) });
  const valuationInput = useMemo(() => ({ ...sensitivityInput, terminalGrowthRate: Number(terminalGrowthRate) || 0 }), [sensitivityInput, terminalGrowthRate]);
  const valuation = trpc.saadi.valuation.useQuery(valuationInput, { enabled: Boolean(selectedStudyId && valuationInput.cashFlows.length && valuationInput.discountRate > valuationInput.terminalGrowthRate) });
  const financingInput = useMemo(() => ({ equityAmount: Number(equityAmount) || 0, debtAmount: Number(debtAmount) || 0, annualInterestRate: Number(debtInterestRate) || 0, termMonths: Number(debtTermMonths) || 0 }), [equityAmount, debtAmount, debtInterestRate, debtTermMonths]);
  const financing = trpc.saadi.financing.useQuery(financingInput, { enabled: Boolean(selectedStudyId) });
  const assumptions = trpc.saadi.assumptions.useQuery(activeCompanyId && organizationId && selectedStudyId ? { organizationId, studyId: selectedStudyId } : { organizationId: 0, studyId: 0 }, { enabled: Boolean(activeCompanyId && organizationId && selectedStudyId) });
  const createAssumption = trpc.saadi.createAssumption.useMutation({ onSuccess: async () => { setAssumptionName(""); setAssumptionValue(""); setAssumptionNotes(""); await assumptions.refetch(); } });
  const extendedIndicators = trpc.saadi.indicators.useQuery({ initialInvestment: Number(initialInvestment) || 1, discountRate: Number(discountRate) || 0, cashFlows: sensitivityInput.cashFlows }, { enabled: Boolean(selectedStudyId && sensitivityInput.cashFlows.length) });
  const financingBalance = useMemo(() => { const totalSources = financingInput.equityAmount + financingInput.debtAmount; const difference = totalSources - (Number(initialInvestment) || 0); const tolerance = 0.01; return { totalSources, difference, balanced: Math.abs(difference) <= tolerance }; }, [financingInput.debtAmount, financingInput.equityAmount, initialInvestment]);
  const scenarios = trpc.saadi.scenarios.useQuery(activeCompanyId && organizationId && selectedStudyId ? { organizationId, companyId: activeCompanyId, studyId: selectedStudyId } : { organizationId: 0, companyId: 0, studyId: 0 }, { enabled: Boolean(activeCompanyId && organizationId && selectedStudyId) });
  const saveScenario = trpc.saadi.saveScenario.useMutation({ onSuccess: async () => { await scenarios.refetch(); } });
  const captureErpSnapshot = trpc.saadi.captureErpAccountingSnapshot.useMutation({ onSuccess: async () => { await snapshots.refetch(); } });
  const variances = trpc.saadi.variances.useQuery(activeCompanyId && organizationId && selectedStudyId ? { organizationId, companyId: activeCompanyId, studyId: selectedStudyId, snapshotId: selectedSnapshotId } : { organizationId: 0, companyId: 0, studyId: 0 }, { enabled: Boolean(activeCompanyId && organizationId && selectedStudyId) });
  const compareVariance = trpc.saadi.compareProjectionToRealized.useMutation({ onSuccess: async () => { await variances.refetch(); } });
  const risks = trpc.saadi.risks.useQuery(activeCompanyId && organizationId && selectedStudyId ? { organizationId, companyId: activeCompanyId, studyId: selectedStudyId } : { organizationId: 0, companyId: 0, studyId: 0 }, { enabled: Boolean(activeCompanyId && organizationId && selectedStudyId) });
  const riskSummary = useMemo(() => { const items = risks.data ?? []; const exposures = items.map((risk) => Number(risk.exposure) || 0); return { totalExposure: exposures.reduce((sum, value) => sum + value, 0), maximumExposure: exposures.length ? Math.max(...exposures) : 0, critical: exposures.filter((value) => value >= 20).length, high: exposures.filter((value) => value >= 12 && value < 20).length, moderate: exposures.filter((value) => value >= 6 && value < 12).length }; }, [risks.data]);
  const createRisk = trpc.saadi.createRisk.useMutation({ onSuccess: async () => { setRiskTitle(""); setRiskDescription(""); await risks.refetch(); } });
  const decisions = trpc.saadi.decisions.useQuery(activeCompanyId && organizationId && selectedStudyId ? { organizationId, companyId: activeCompanyId, studyId: selectedStudyId } : { organizationId: 0, companyId: 0, studyId: 0 }, { enabled: Boolean(activeCompanyId && organizationId && selectedStudyId) });
  const submitDecision = trpc.saadi.submitDecision.useMutation({ onSuccess: async () => { setDecisionJustification(""); await decisions.refetch(); } });
  const generateReport = trpc.saadi.generateReport.useMutation();
  const documents = trpc.saadi.documents.useQuery(activeCompanyId && organizationId && selectedStudyId ? { organizationId, studyId: selectedStudyId } : { organizationId: 0, studyId: 0 }, { enabled: Boolean(activeCompanyId && organizationId && selectedStudyId) });
  const addDocument = trpc.saadi.addDocument.useMutation({ onSuccess: async () => { await documents.refetch(); } });
  const reviewDocument = trpc.saadi.reviewDocument.useMutation({ onSuccess: async () => { await documents.refetch(); } });
  const projections = trpc.saadi.projections.useQuery(activeCompanyId && organizationId && selectedStudyId ? { organizationId, studyId: selectedStudyId } : { organizationId: 0, studyId: 0 }, { enabled: Boolean(activeCompanyId && organizationId && selectedStudyId) });
  const alerts = trpc.saadi.alerts.useQuery(activeCompanyId && organizationId && selectedStudyId ? { organizationId, companyId: activeCompanyId, studyId: selectedStudyId } : { organizationId: 0, companyId: 0, studyId: 0 }, { enabled: Boolean(activeCompanyId && organizationId && selectedStudyId) });
  const validations = trpc.saadi.validations.useQuery(activeCompanyId && organizationId && selectedStudyId ? { organizationId, companyId: activeCompanyId, studyId: selectedStudyId } : { organizationId: 0, companyId: 0, studyId: 0 }, { enabled: Boolean(activeCompanyId && organizationId && selectedStudyId) });
  const provenance = trpc.saadi.provenance.useQuery(
    activeCompanyId && organizationId && selectedSnapshotId ? { companyId: activeCompanyId, organizationId, snapshotId: selectedSnapshotId } : { companyId: 0, organizationId: 0, snapshotId: 0 },
    { enabled: Boolean(activeCompanyId && organizationId && selectedSnapshotId) },
  );
  const utils = trpc.useUtils();
  const createStudy = trpc.saadi.createStudy.useMutation({
    onSuccess: async () => { setCode(""); setName(""); await utils.saadi.studies.invalidate(); },
  });
  const createExternalStudy = trpc.saadi.createExternalStudy.useMutation({
    onSuccess: async (result) => { setCode(""); setName(""); setStudyDescription(""); setExternalLegalName(""); setExternalNif(""); setExternalActivity(""); setExternalProvince(""); setExternalMunicipality(""); setExternalAddress(""); setExternalEmail(""); setStudyEntityType("ERP"); await utils.saadi.studies.invalidate(); if (result.study?.id) setStudyId(result.study.id); },
  });
  const transitionVersion = trpc.saadi.transitionVersion.useMutation({ onSuccess: async () => { await versions.refetch(); } });
  const transitionWorkflow = trpc.saadi.transitionWorkflow.useMutation({ onSuccess: async () => { await studies.refetch(); } });
  const statusText = useMemo(() => {
    if (companies.isLoading) return "A carregar empresas autorizadas…";
    if (!rows.length) return "Não existem empresas autorizadas para o utilizador actual.";
    return `${rows.length} empresa${rows.length === 1 ? "" : "s"} disponível${rows.length === 1 ? "" : "eis"}.`;
  }, [companies.isLoading, rows.length]);
  const orderedScenarios = useMemo(() => [...(scenarios.data ?? [])].sort((left, right) => Number(right.indicators?.npv ?? -Infinity) - Number(left.indicators?.npv ?? -Infinity)), [scenarios.data]);
  const readiness = useMemo(() => {
    const checks = [
      { key: "study", label: "Estudo criado", done: Boolean(selectedStudyId) },
      { key: "inputs", label: "Premissas financeiras guardadas", done: Boolean(feasibility.data?.input) },
      { key: "financing", label: "Fontes de financiamento equilibradas", done: Boolean(feasibility.data?.input) && financingBalance.balanced },
      { key: "result", label: "Análise financeira calculada", done: Boolean(feasibility.data?.result) },
      { key: "snapshot", label: "Dados realizados capturados", done: Boolean(snapshots.data?.length) },
      { key: "version", label: "Versão para validação", done: Boolean(versions.data?.length) },
      { key: "risk", label: "Riscos avaliados", done: Boolean(risks.data?.length) },
      { key: "decision", label: "Decisão humana registada", done: Boolean(decisions.data?.length) },
    ];
    const completed = checks.filter((check) => check.done).length;
    return { checks, completed, percentage: Math.round((completed / checks.length) * 100) };
  }, [decisions.data, feasibility.data, financingBalance.balanced, risks.data, selectedStudyId, snapshots.data, versions.data]);

  return (
    <div className="space-y-4 p-4 text-[#1d2a38]">
      <div className="flex items-start justify-between gap-3 border-b border-[#dbe5f1] pb-3">
        <div>
          <p className="text-[10px] font-semibold uppercase tracking-[0.16em] text-[#477514]">Sistema autónomo de análise</p>
          <h1 className="mt-1 flex items-center gap-2 text-xl font-semibold text-[#102a43]"><FlaskConical className="h-5 w-5 text-[#1267d6]" /> SAADI</h1>
          <p className="mt-1 text-xs text-slate-500">Estudos e projecções com dados capturados do BALANCERTS.ERP, sem alterar os registos operacionais.</p>
        </div>
        <Badge className="border-emerald-200 bg-emerald-50 text-emerald-700"><ShieldCheck className="mr-1 h-3.5 w-3.5" /> Escopo protegido</Badge>
      </div>
      <Card className="rounded-sm border-[#b9d2ef] bg-[#f8fbff] shadow-none"><CardHeader className="py-2"><CardTitle className="flex items-center gap-2 text-sm text-[#102a43]"><ShieldCheck className="h-4 w-4 text-[#477514]" /> Fonte normativa PGCA</CardTitle></CardHeader><CardContent className="grid gap-2 text-xs md:grid-cols-4"><span className="font-semibold">{pgcNormativeContext.isLoading ? "A verificar…" : pgcNormativeContext.data?.data.available ? "Versão activa disponível" : "Sem versão activa"}</span><span>Contas confirmadas: {pgcNormativeContext.data?.data.accounts.length ?? 0}</span><span>Fontes confirmadas: {pgcNormativeContext.data?.data.sources.length ?? 0}</span><span className="text-slate-500">{pgcNormativeContext.data?.data.confirmedOnly ? "Apenas dados confirmados" : "Leitura normativa indisponível"}</span></CardContent></Card>

      <Card className="rounded-sm border-[#bfc9d4] bg-[#fbfcfd] shadow-none">
        <CardHeader className="pb-2"><CardTitle className="flex items-center gap-2 text-sm text-[#102a43]"><Building2 className="h-4 w-4 text-[#1267d6]" /> Contexto da análise</CardTitle></CardHeader>
        <CardContent className="space-y-2">
          <Label htmlFor="saadi-company">Empresa de trabalho</Label>
          <select id="saadi-company" aria-label="Empresa de trabalho SAADI" value={activeCompanyId ?? ""} onChange={(event) => { setCompanyId(Number(event.target.value)); setStudyId(undefined); }} className="h-9 w-full max-w-xl rounded-md border border-[#dbe5f1] bg-white px-2 text-xs">
            <option value="">Seleccionar empresa</option>
            {rows.map(({ company }) => <option key={company.id} value={company.id}>{companyDisplayName(company.name)} · {company.nif}</option>)}
          </select>
          <p className="text-xs text-slate-500">{statusText}{user?.name ? ` Utilizador: ${user.name}.` : ""}</p>
        </CardContent>
      </Card>

      <div className="grid gap-4 lg:grid-cols-[1fr_1.4fr]">
        <Card className="rounded-sm border-[#bfc9d4] bg-[#fbfcfd] shadow-none">
          <CardHeader className="pb-2"><CardTitle className="text-sm text-[#102a43]">Novo estudo</CardTitle></CardHeader>
          <CardContent>
            <div className="space-y-2">
              <select aria-label="Origem da empresa do estudo" value={studyEntityType} onChange={(event) => setStudyEntityType(event.target.value as typeof studyEntityType)} className="h-9 w-full rounded-md border border-[#dbe5f1] bg-white px-2 text-xs"><option value="ERP">Empresa cadastrada no BALANCERTS.ERP</option><option value="EXTERNA">Empresa externa — não criar no ERP</option></select>
              <Input aria-label="Código do estudo" placeholder="Código, por exemplo INV-001" value={code} onChange={(event) => setCode(event.target.value)} />
              <Input aria-label="Nome do estudo" placeholder="Nome do estudo" value={name} onChange={(event) => setName(event.target.value)} />
              <select aria-label="Tipo de estudo" value={studyType} onChange={(event) => setStudyType(event.target.value)} className="h-9 w-full rounded-md border border-[#dbe5f1] bg-white px-2 text-xs"><option value="INVESTIMENTO">Investimento</option><option value="NOVO_PROJECTO">Novo projecto</option><option value="EXPANSAO">Expansão de negócio</option><option value="AQUISICAO_EQUIPAMENTO">Aquisição de equipamento</option><option value="ABERTURA_UNIDADE">Abertura de nova unidade</option><option value="CONSTRUCAO">Construção</option><option value="PROJECTO_IMOBILIARIO">Projecto imobiliário</option><option value="PROJECTO_AGRICOLA">Projecto agrícola</option><option value="PROJECTO_INDUSTRIAL">Projecto industrial</option><option value="PROJECTO_COMERCIAL">Projecto comercial</option><option value="SERVICOS">Prestação de serviços</option><option value="OUTRO">Outro</option></select>
              <select aria-label="Domínio do investimento" value={investmentDomain} onChange={(event) => setInvestmentDomain(event.target.value as typeof investmentDomain)} className="h-9 w-full rounded-md border border-[#dbe5f1] bg-white px-2 text-xs"><option value="OUTRO">Outro investimento</option><option value="IMOBILIARIO">Imobiliário</option><option value="AGRICULTURA">Agricultura</option><option value="INDUSTRIA">Indústria</option><option value="ENERGIA">Energia</option><option value="HOTELARIA">Hotelaria</option><option value="LOGISTICA">Logística</option></select>
              <select aria-label="Horizonte de projecção" value={projectionHorizonYears} onChange={(event) => setProjectionHorizonYears(event.target.value)} className="h-9 w-full rounded-md border border-[#dbe5f1] bg-white px-2 text-xs"><option value="3">3 anos</option><option value="5">5 anos</option><option value="7">7 anos</option><option value="10">10 anos</option><option value="15">15 anos</option><option value="20">20 anos</option></select>
              <textarea aria-label="Descrição do projecto" placeholder="Descrição do projecto" value={studyDescription} onChange={(event) => setStudyDescription(event.target.value)} className="min-h-20 w-full rounded-md border border-[#dbe5f1] bg-white px-2 py-2 text-xs" />
              {studyEntityType === "EXTERNA" && <div className="space-y-2 rounded border border-amber-200 bg-amber-50 p-2"><p className="text-[11px] font-medium text-amber-900">A empresa externa ficará vinculada exclusivamente a este estudo e não será criada no cadastro operacional.</p><Input aria-label="Denominação da empresa externa" placeholder="Denominação social" value={externalLegalName} onChange={(event) => setExternalLegalName(event.target.value)} /><Input aria-label="NIF da empresa externa" placeholder="NIF" value={externalNif} onChange={(event) => setExternalNif(event.target.value)} /><Input aria-label="Actividade da empresa externa" placeholder="Actividade principal" value={externalActivity} onChange={(event) => setExternalActivity(event.target.value)} /><div className="grid grid-cols-2 gap-2"><Input aria-label="Província da empresa externa" placeholder="Província" value={externalProvince} onChange={(event) => setExternalProvince(event.target.value)} /><Input aria-label="Município da empresa externa" placeholder="Município" value={externalMunicipality} onChange={(event) => setExternalMunicipality(event.target.value)} /></div><Input aria-label="Morada da empresa externa" placeholder="Morada" value={externalAddress} onChange={(event) => setExternalAddress(event.target.value)} /><Input aria-label="Email da empresa externa" placeholder="Email" type="email" value={externalEmail} onChange={(event) => setExternalEmail(event.target.value)} /></div>}
              {studyEntityType === "ERP" ? <Button type="button" disabled={!activeCompanyId || !organizationId || !code.trim() || !name.trim() || createStudy.isPending} onClick={() => { if (activeCompanyId && organizationId && code.trim() && name.trim()) createStudy.mutate({ companyId: activeCompanyId, organizationId, studyCode: code, name, investmentDomain, baseCurrency: selected?.company.functionalCurrency ?? "AOA", projectionHorizonYears: Number(projectionHorizonYears) }); }} className="w-full bg-[#1267d6]"><Plus className="mr-1 h-4 w-4" />{createStudy.isPending ? "A registar…" : "Criar estudo ERP"}</Button> : <Button type="button" disabled={!organizationId || !code.trim() || !name.trim() || !externalLegalName.trim() || createExternalStudy.isPending} onClick={() => { if (organizationId && code.trim() && name.trim() && externalLegalName.trim()) createExternalStudy.mutate({ organizationId, studyCode: code, name, studyType, description: studyDescription, investmentDomain, baseCurrency: "AOA", projectionHorizonYears: Number(projectionHorizonYears), externalCompany: { legalName: externalLegalName, nif: externalNif || undefined, activity: externalActivity || undefined, province: externalProvince || undefined, municipality: externalMunicipality || undefined, address: externalAddress || undefined, email: externalEmail || undefined } }); }} className="w-full bg-[#1267d6]"><Plus className="mr-1 h-4 w-4" />{createExternalStudy.isPending ? "A registar…" : "Criar estudo externo"}</Button>}
              {(createStudy.error || createExternalStudy.error) && <p role="alert" className="text-xs text-rose-700">Não foi possível criar o estudo. Verifique os dados e as permissões.</p>}
              {(createStudy.isSuccess || createExternalStudy.isSuccess) && <p role="status" className="text-xs text-emerald-700">Estudo criado e pronto para configuração.</p>}
            </div>
          </CardContent>
        </Card>

        <Card className="rounded-sm border-[#bfc9d4] bg-[#fbfcfd] shadow-none">
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2"><CardTitle className="text-sm text-[#102a43]">Estudos da empresa</CardTitle><Button type="button" size="sm" variant="outline" onClick={() => studies.refetch()} disabled={studies.isFetching}><RefreshCw className="mr-1 h-3.5 w-3.5" /> Actualizar</Button></CardHeader>
          <CardContent>
            {studies.isLoading ? <p className="text-xs text-slate-500">A carregar estudos…</p> : studies.error ? <p className="text-xs text-rose-700">Não foi possível carregar os estudos. Verifique as permissões da empresa.</p> : !activeCompanyId ? <p className="text-xs text-slate-500">Seleccione uma empresa para consultar o seu contexto SAADI.</p> : !(studies.data ?? []).length ? <p className="text-xs text-slate-500">Ainda não existem estudos nesta empresa.</p> : <div className="space-y-2">{(studies.data ?? []).map((study) => <button type="button" key={study.id} onClick={() => setStudyId(study.id)} className={`flex w-full items-center justify-between rounded border px-3 py-2 text-left ${selectedStudyId === study.id ? "border-[#1267d6] bg-[#eef5ff]" : "border-[#dbe5f1] bg-white"}`}><div><p className="text-xs font-semibold text-[#102a43]">{study.name}</p><p className="text-[11px] text-slate-500">{study.studyCode} · {study.baseCurrency} · {study.investmentDomain === "IMOBILIARIO" ? "Imobiliário" : study.investmentDomain === "AGRICULTURA" ? "Agricultura" : study.investmentDomain === "INDUSTRIA" ? "Indústria" : study.investmentDomain === "ENERGIA" ? "Energia" : study.investmentDomain === "HOTELARIA" ? "Hotelaria" : study.investmentDomain === "LOGISTICA" ? "Logística" : "Outro investimento"}</p><p className="text-[10px] text-slate-500">Ciclo: {workflowStatusLabel(study.workflowStatus)}</p></div><Badge variant="outline">{studyStatusLabel(study.status)}</Badge></button>)}</div>}
          </CardContent>
        </Card>
        <Card className="rounded-sm border-[#bfc9d4] bg-[#fbfcfd] shadow-none"><CardHeader className="pb-2"><CardTitle className="text-sm text-[#102a43]">Ciclo de vida do estudo</CardTitle></CardHeader><CardContent className="space-y-2"><p className="text-[11px] text-slate-500">As transições são validadas no servidor e ficam registadas na auditoria.</p><div className="flex flex-wrap items-center gap-2"><span className="text-xs text-slate-600">Estado actual: <strong>{workflowStatusLabel((studies.data ?? []).find((study) => study.id === selectedStudyId)?.workflowStatus ?? "RASCUNHO")}</strong></span><select aria-label="Próximo estado do estudo" value={nextWorkflowStatus} onChange={(event) => setNextWorkflowStatus(event.target.value as typeof nextWorkflowStatus)} className="h-9 rounded-md border border-[#dbe5f1] bg-white px-2 text-xs"><option value="RASCUNHO">Rascunho</option><option value="EM_ANALISE">Em análise</option><option value="AGUARDANDO_VALIDACAO">Aguardando validação</option><option value="VALIDADO">Validado</option><option value="CONCLUIDO">Concluído</option><option value="ARQUIVADO">Arquivado</option></select><Button type="button" size="sm" variant="outline" disabled={!selectedStudyId || !organizationId || transitionWorkflow.isPending} onClick={() => { if (selectedStudyId && organizationId) transitionWorkflow.mutate({ organizationId, studyId: selectedStudyId, nextStatus: nextWorkflowStatus }); }}>{transitionWorkflow.isPending ? "A actualizar…" : "Actualizar estado"}</Button></div>{transitionWorkflow.error && <p role="alert" className="text-[11px] text-rose-700">Não foi possível efectuar a transição. Verifique o checklist e a sequência permitida.</p>}{transitionWorkflow.isSuccess && <p role="status" className="text-[11px] text-emerald-700">Estado do estudo actualizado e auditado.</p>}</CardContent></Card>
      </div>

      <Card className="rounded-sm border-[#bfc9d4] bg-[#fbfcfd] shadow-none">
        <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2"><CardTitle className="text-sm text-[#102a43]">Prontidão do estudo</CardTitle><Badge variant="outline" className={readiness.percentage === 100 ? "border-emerald-200 text-emerald-700" : "border-amber-200 text-amber-700"}>{readiness.percentage}% concluído</Badge></CardHeader>
        <CardContent className="space-y-3"><div className="h-2 overflow-hidden rounded-full bg-slate-100"><div className={`h-full rounded-full transition-all ${readiness.percentage === 100 ? "bg-emerald-500" : "bg-[#1267d6]"}`} style={{ width: `${readiness.percentage}%` }} /></div><div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-4">{readiness.checks.map((check) => <div key={check.key} className={`rounded border px-2 py-2 text-[11px] ${check.done ? "border-emerald-200 bg-emerald-50 text-emerald-800" : "border-amber-200 bg-amber-50 text-amber-800"}`}><span className="mr-1 font-semibold">{check.done ? "✓" : "!"}</span>{check.label}</div>)}</div>{!selectedStudyId ? <p className="text-[11px] text-slate-500">Crie ou seleccione um estudo para iniciar o preenchimento guiado.</p> : readiness.percentage < 100 ? <p className="text-[11px] text-slate-500">Complete os itens pendentes pela ordem apresentada. Nenhum passo altera os registos operacionais do BALANCERTS.ERP.</p> : <p className="text-[11px] text-emerald-700">O estudo tem os elementos essenciais registados para análise e decisão.</p>}</CardContent>
      </Card>

      <div className="grid gap-4 lg:grid-cols-2">
        <Card className="rounded-sm border-[#bfc9d4] bg-[#fbfcfd] shadow-none">
          <CardHeader className="pb-2"><CardTitle className="text-sm text-[#102a43]">Capturas de dados</CardTitle></CardHeader>
          <CardContent>{snapshots.isLoading ? <p className="text-xs text-slate-500">A carregar capturas…</p> : !(snapshots.data ?? []).length ? <p className="text-xs text-slate-500">Sem capturas para o estudo seleccionado.</p> : <div className="space-y-2"><label className="block text-[11px] font-semibold text-[#102a43]">Captura usada nas análises<select aria-label="Seleccionar captura de dados para análise" value={selectedSnapshotId ?? ""} onChange={(event) => setSnapshotId(event.target.value ? Number(event.target.value) : undefined)} className="mt-1 h-8 w-full rounded border border-[#dbe5f1] bg-white px-2 text-xs font-normal"><option value="">Seleccione uma captura</option>{(snapshots.data ?? []).map((snapshot) => <option key={`snapshot-option-${snapshot.id}`} value={snapshot.id}>{snapshotStatusLabel(snapshot.status)} · {snapshot.sourceFingerprint.slice(0, 12)}…</option>)}</select></label>{(snapshots.data ?? []).map((snapshot) => <div key={snapshot.id} className={`rounded border p-2 ${selectedSnapshotId === snapshot.id ? "border-[#1267d6] bg-[#f3f8ff]" : "border-[#dbe5f1] bg-white"}`}><div className="flex justify-between text-xs"><span className="font-semibold text-[#102a43]">{snapshotStatusLabel(snapshot.status)}</span><span className="text-slate-500">{snapshot.sourceFingerprint.slice(0, 12)}…</span></div><p className="mt-1 text-[11px] text-slate-500">Chave de repetição segura: {snapshot.idempotencyKey}</p></div>)}</div>}</CardContent>
        </Card>

        <Card className="rounded-sm border-[#bfc9d4] bg-[#fbfcfd] shadow-none">
          <CardHeader className="pb-2"><CardTitle className="text-sm text-[#102a43]">Versões e origem dos dados</CardTitle></CardHeader>
          <CardContent>{versions.isLoading ? <p className="text-xs text-slate-500">A carregar versões…</p> : !(versions.data ?? []).length ? <p className="text-xs text-slate-500">Sem versões criadas para o estudo seleccionado.</p> : <div className="space-y-2">{(versions.data ?? []).map((version) => <div key={version.id} className="rounded border border-[#dbe5f1] bg-white p-2"><div className="flex justify-between gap-2 text-xs"><span className="font-semibold text-[#102a43]">Versão {version.versionNumber}</span><Badge variant="outline">{versionStatusLabel(version.status)}</Badge></div><p className="mt-1 text-[11px] text-slate-500">Integridade: {version.versionHash.slice(0, 16)}… · Criada por {version.createdBy}</p><div className="mt-2 flex gap-2">{version.status === "IN_REVIEW" && <Button type="button" size="sm" className="bg-[#477514]" disabled={transitionVersion.isPending} onClick={() => activeCompanyId && organizationId && transitionVersion.mutate({ organizationId, companyId: activeCompanyId, versionId: version.id, decision: "APPROVE" })}>Aprovar</Button>}{version.status !== "ARCHIVED" && <Button type="button" size="sm" variant="outline" disabled={transitionVersion.isPending} onClick={() => activeCompanyId && organizationId && transitionVersion.mutate({ organizationId, companyId: activeCompanyId, versionId: version.id, decision: "ARCHIVE" })}>Arquivar</Button>}</div></div>)}</div>}{selectedSnapshotId && <p className="mt-2 text-[11px] text-slate-500">{provenance.isLoading ? "A carregar origem da captura…" : provenance.data?.length ? `${provenance.data.length} registo${provenance.data.length === 1 ? "" : "s"} de origem associado${provenance.data.length === 1 ? "" : "s"}.` : "A captura ainda não tem detalhes de origem registados."}</p>}</CardContent>
        </Card>
      </div>
      <Card className="rounded-sm border-[#bfc9d4] bg-[#fbfcfd] shadow-none">
        <CardHeader className="pb-2"><CardTitle className="text-sm text-[#102a43]">Estudo de Viabilidade — análise financeira</CardTitle></CardHeader>
        <CardContent className="space-y-4">
          {!selectedStudyId ? <p className="text-xs text-slate-500">Crie ou seleccione um estudo para iniciar a análise financeira.</p> : <>
            <div className="grid gap-3 md:grid-cols-3">
              <div><Label htmlFor="saadi-investment">Investimento inicial</Label><Input id="saadi-investment" type="number" min="0" step="0.01" value={initialInvestment} onChange={(event) => setInitialInvestment(event.target.value)} /></div>
              <div><Label htmlFor="saadi-rate">Taxa de desconto anual</Label><Input id="saadi-rate" type="number" min="-0.99" max="10" step="0.01" value={discountRate} onChange={(event) => setDiscountRate(event.target.value)} /><p className="mt-1 text-[11px] text-slate-500">Use 0,15 para 15%.</p></div>
              <div><Label htmlFor="saadi-cashflows">Fluxos de caixa anuais</Label><Input id="saadi-cashflows" value={cashFlows} onChange={(event) => setCashFlows(event.target.value)} placeholder="300000,350000,400000" /></div>
              <div><Label htmlFor="saadi-equity">Capital próprio</Label><Input id="saadi-equity" type="number" min="0" step="0.01" value={equityAmount} onChange={(event) => setEquityAmount(event.target.value)} /></div>
              <div><Label htmlFor="saadi-debt">Financiamento externo</Label><Input id="saadi-debt" type="number" min="0" step="0.01" value={debtAmount} onChange={(event) => setDebtAmount(event.target.value)} /></div>
              <div><Label htmlFor="saadi-debt-rate">Taxa anual da dívida</Label><Input id="saadi-debt-rate" type="number" min="0" max="1" step="0.01" value={debtInterestRate} onChange={(event) => setDebtInterestRate(event.target.value)} /></div>
              <div><Label htmlFor="saadi-debt-term">Prazo da dívida (meses)</Label><Input id="saadi-debt-term" type="number" min="0" max="360" value={debtTermMonths} onChange={(event) => setDebtTermMonths(event.target.value)} /></div>
            </div>
            {financing.data && <div className="rounded border border-[#dbe5f1] bg-[#f8fafc] p-2 text-[11px] text-slate-600">Estrutura do financiamento: capital próprio <strong>{financing.data.equityAmount.toLocaleString("pt-PT", { maximumFractionDigits: 0 })}</strong> · dívida <strong>{financing.data.debtAmount.toLocaleString("pt-PT", { maximumFractionDigits: 0 })}</strong> · prestação mensal <strong>{financing.data.monthlyPayment.toLocaleString("pt-PT", { maximumFractionDigits: 0 })}</strong> · juros totais <strong>{financing.data.totalInterest.toLocaleString("pt-PT", { maximumFractionDigits: 0 })}</strong></div>}
            <div className={`rounded border p-2 text-[11px] ${financingBalance.balanced ? "border-emerald-200 bg-emerald-50 text-emerald-800" : "border-amber-200 bg-amber-50 text-amber-800"}`}><strong>{financingBalance.balanced ? "Financiamento equilibrado" : financingBalance.difference < 0 ? "Financiamento insuficiente" : "Financiamento excedente"}</strong> · Fontes totais {financingBalance.totalSources.toLocaleString("pt-PT", { maximumFractionDigits: 0 })} · Diferença {Math.abs(financingBalance.difference).toLocaleString("pt-PT", { maximumFractionDigits: 0 })}</div>
            <div className="flex flex-wrap gap-2">
              <Button type="button" className="bg-[#1267d6]" disabled={saveFeasibility.isPending || !activeCompanyId || !organizationId} onClick={() => { const flows = cashFlows.split(",").map((value) => Number(value.trim())); if (activeCompanyId && organizationId && selectedStudyId) saveFeasibility.mutate({ organizationId, companyId: activeCompanyId, studyId: selectedStudyId, feasibility: { initialInvestment: Number(initialInvestment), discountRate: Number(discountRate), cashFlows: flows, currency: selected?.company.functionalCurrency ?? "AOA", equityAmount: Number(equityAmount), debtAmount: Number(debtAmount), debtInterestRate: Number(debtInterestRate), debtTermMonths: Number(debtTermMonths) } }); }}>Guardar premissas</Button>
              <Button type="button" variant="outline" disabled={calculateFeasibility.isPending || !feasibility.data?.input} onClick={() => { if (activeCompanyId && organizationId && selectedStudyId) calculateFeasibility.mutate({ organizationId, companyId: activeCompanyId, studyId: selectedStudyId }); }}>Calcular viabilidade</Button>
              {saveFeasibility.error && <p role="alert" className="self-center text-xs text-rose-700">Não foi possível guardar as premissas. Verifique os valores.</p>}
              {calculateFeasibility.error && <p role="alert" className="self-center text-xs text-rose-700">Não foi possível calcular. Verifique se existem fluxos válidos.</p>}
              {saveFeasibility.isSuccess && <p role="status" className="self-center text-xs text-emerald-700">Premissas guardadas.</p>}
            </div>
            <div className="flex flex-wrap items-end gap-2 border-t border-[#dbe5f1] pt-3"><div className="min-w-[220px] flex-1"><Label htmlFor="saadi-scenario">Nome do cenário</Label><Input id="saadi-scenario" value={scenarioName} onChange={(event) => setScenarioName(event.target.value)} placeholder="Cenário optimista" /></div><Button type="button" variant="outline" disabled={saveScenario.isPending || !scenarioName.trim() || !financingBalance.balanced} onClick={() => { const flows = cashFlows.split(",").map((value) => Number(value.trim())); if (activeCompanyId && organizationId && selectedStudyId && financingBalance.balanced) saveScenario.mutate({ organizationId, companyId: activeCompanyId, studyId: selectedStudyId, name: scenarioName, feasibility: { initialInvestment: Number(initialInvestment), discountRate: Number(discountRate), cashFlows: flows, currency: selected?.company.functionalCurrency ?? "AOA", equityAmount: Number(equityAmount), debtAmount: Number(debtAmount), debtInterestRate: Number(debtInterestRate), debtTermMonths: Number(debtTermMonths) } }); }}>Guardar cenário calculado</Button></div>{!financingBalance.balanced && <p className="text-[10px] text-amber-700">O cenário fica disponível depois de corrigir a diferença entre o investimento inicial e as fontes de financiamento.</p>}
            {orderedScenarios.length ? <div className="space-y-2"><p className="text-xs font-semibold text-[#102a43]">Comparação de cenários</p>{orderedScenarios.map((scenario, index) => { const indicators = scenario.indicators; const decision = indicators?.decision ?? scenario.decision; return <div key={scenario.id} className={`rounded border px-3 py-2 text-xs ${index === 0 ? "border-emerald-300 bg-emerald-50/40" : "border-[#dbe5f1] bg-white"}`}><div className="flex items-center justify-between"><span className="font-semibold text-[#102a43]">{scenario.name}{index === 0 ? <span className="ml-2 rounded bg-emerald-100 px-1.5 py-0.5 text-[10px] text-emerald-800">Melhor VPL</span> : null}</span><span className={decision === "PROSSEGUIR" ? "font-semibold text-emerald-700" : decision === "REJEITAR" ? "font-semibold text-rose-700" : "font-semibold text-amber-700"}>{decision === "PROSSEGUIR" ? "Prosseguir" : decision === "REJEITAR" ? "Rejeitar" : "Rever"}</span></div><p className="mt-1 text-[10px] text-slate-500">VPL: {indicators?.npv == null ? "—" : Number(indicators.npv).toLocaleString("pt-PT", { maximumFractionDigits: 0 })} · TIR: {indicators?.irr == null ? "—" : `${(Number(indicators.irr) * 100).toFixed(1)}%`} · Retorno: {indicators?.paybackMonths == null ? "—" : `${Number(indicators.paybackMonths).toFixed(1)} períodos`}</p><p className="text-[10px] text-slate-500">Capital próprio: {Number(scenario.equityAmount ?? 0).toLocaleString("pt-PT", { maximumFractionDigits: 0 })} · Dívida: {Number(scenario.debtAmount ?? 0).toLocaleString("pt-PT", { maximumFractionDigits: 0 })} · Serviço mensal: {indicators?.monthlyPayment == null ? "—" : Number(indicators.monthlyPayment).toLocaleString("pt-PT", { maximumFractionDigits: 0 })}</p></div>; })}</div> : null}
            <div className="rounded border border-[#dbe5f1] bg-[#f6faff] p-3">
              <div className="flex items-center gap-2"><Database className="h-4 w-4 text-[#1267d6]" /><p className="text-xs font-semibold text-[#102a43]">Dados realizados do BALANCERTS.ERP</p></div>
              <p className="mt-1 text-[11px] text-slate-500">Captura somente de leitura. Os movimentos contabilísticos do ERP não serão alterados.</p>
              <div className="mt-3 flex flex-wrap items-end gap-2">
                <div><Label htmlFor="saadi-period">Período contabilístico</Label><Input id="saadi-period" type="number" min="1" value={periodId} onChange={(event) => setPeriodId(event.target.value)} className="w-32" /></div>
                <Button type="button" variant="outline" disabled={captureErpSnapshot.isPending || !activeCompanyId || !organizationId || !selectedStudyId} onClick={() => { if (activeCompanyId && organizationId && selectedStudyId) captureErpSnapshot.mutate({ studyId: selectedStudyId, request: { organizationId, companyId: activeCompanyId, periodIds: [Number(periodId)], currency: selected?.company.functionalCurrency ?? "AOA", purpose: "Análise do realizado contabilístico", contractVersion: "v1.0", correlationId: `erp-accounting-${selectedStudyId}-${periodId}`, includeHrDetails: false } }); }}><Database className="mr-1 h-3.5 w-3.5" />{captureErpSnapshot.isPending ? "A capturar…" : "Capturar realizado"}</Button>
                {captureErpSnapshot.isSuccess && <span className="text-[11px] text-emerald-700">Captura concluída com proveniência.</span>}
                {captureErpSnapshot.error && <span role="alert" className="text-[11px] text-rose-700">Não foi possível capturar o período seleccionado.</span>}
              </div>
            </div>
            <div className="rounded border border-[#dbe5f1] bg-white p-3">
              <div className="flex items-center gap-2"><GitCompareArrows className="h-4 w-4 text-[#1267d6]" /><p className="text-xs font-semibold text-[#102a43]">Projectado versus realizado</p></div>
              <p className="mt-1 text-[11px] text-slate-500">Compare um valor projectado com uma métrica realizada proveniente da captura ERP.</p>
              <div className="mt-3 flex flex-wrap items-end gap-2">
                <div className="min-w-[190px]"><Label htmlFor="saadi-variance-metric">Métrica realizada</Label><select id="saadi-variance-metric" value={varianceMetric} onChange={(event) => setVarianceMetric(event.target.value)} className="h-9 w-full rounded-md border border-[#dbe5f1] bg-white px-2 text-xs"><option value="resultadoLiquidoRealizado">Resultado líquido realizado</option><option value="receitaRealizada">Receita realizada</option><option value="despesasRealizadas">Despesas realizadas</option></select></div>
                <div><Label htmlFor="saadi-projected-value">Valor projectado</Label><Input id="saadi-projected-value" type="number" step="0.01" value={projectedValue} onChange={(event) => setProjectedValue(event.target.value)} className="w-36" /></div>
                <Button type="button" variant="outline" disabled={compareVariance.isPending || !selectedSnapshotId} onClick={() => { if (activeCompanyId && organizationId && selectedStudyId && selectedSnapshotId) compareVariance.mutate({ organizationId, companyId: activeCompanyId, studyId: selectedStudyId, snapshotId: selectedSnapshotId, metric: varianceMetric, projectedValue: Number(projectedValue), currency: selected?.company.functionalCurrency ?? "AOA" }); }}><GitCompareArrows className="mr-1 h-3.5 w-3.5" />{compareVariance.isPending ? "A comparar…" : "Calcular desvio"}</Button>
              </div>
              {variances.data?.length ? <div className="mt-3 space-y-1">{variances.data.map((variance) => <div key={variance.id} className="flex flex-wrap items-center justify-between rounded bg-[#f8fafc] px-2 py-1 text-[11px]"><span>{variance.metric === "resultadoLiquidoRealizado" ? "Resultado líquido" : variance.metric === "receitaRealizada" ? "Receita" : "Despesas"}</span><span>Projectado: {Number(variance.projectedValue).toLocaleString("pt-PT")} · Realizado: {Number(variance.realizedValue).toLocaleString("pt-PT")} · Desvio: {Number(variance.absoluteVariance).toLocaleString("pt-PT")}</span></div>)}</div> : <p className="mt-2 text-[11px] text-slate-500">Ainda não existem desvios calculados para esta captura.</p>}
              {compareVariance.error && <p role="alert" className="mt-2 text-[11px] text-rose-700">Não foi possível calcular o desvio. Capture primeiro os dados realizados.</p>}
            </div>
            <div className="rounded border border-[#dbe5f1] bg-white p-3">
              <div className="flex items-center gap-2"><AlertTriangle className="h-4 w-4 text-amber-600" /><p className="text-xs font-semibold text-[#102a43]">Riscos do investimento</p></div>
              <p className="mt-1 text-[11px] text-slate-500">Registe probabilidade e impacto numa escala de 1 a 5. A exposição é calculada pelo servidor.</p>
              <div className="mt-3 grid gap-2 md:grid-cols-4"><Input aria-label="Título do risco" placeholder="Título do risco" value={riskTitle} onChange={(event) => setRiskTitle(event.target.value)} /><Input aria-label="Descrição do risco" placeholder="Descrição e impacto esperado" value={riskDescription} onChange={(event) => setRiskDescription(event.target.value)} /><Input aria-label="Probabilidade do risco" type="number" min="1" max="5" value={riskProbability} onChange={(event) => setRiskProbability(event.target.value)} /><Input aria-label="Impacto do risco" type="number" min="1" max="5" value={riskImpact} onChange={(event) => setRiskImpact(event.target.value)} /></div>
              <div className="mt-2 flex flex-wrap items-center gap-2"><select aria-label="Resposta ao risco" value={riskResponse} onChange={(event) => setRiskResponse(event.target.value as typeof riskResponse)} className="h-9 rounded-md border border-[#dbe5f1] bg-white px-2 text-xs"><option value="REDUZIR">Reduzir</option><option value="EVITAR">Evitar</option><option value="TRANSFERIR">Transferir</option><option value="ACEITAR">Aceitar</option></select><Button type="button" variant="outline" disabled={createRisk.isPending || !riskTitle.trim() || !riskDescription.trim()} onClick={() => { if (activeCompanyId && organizationId && selectedStudyId) createRisk.mutate({ organizationId, companyId: activeCompanyId, studyId: selectedStudyId, title: riskTitle, description: riskDescription, probability: Number(riskProbability), impact: Number(riskImpact), response: riskResponse }); }}><AlertTriangle className="mr-1 h-3.5 w-3.5" />{createRisk.isPending ? "A registar…" : "Registar risco"}</Button>{createRisk.isSuccess && <span className="text-[11px] text-emerald-700">Risco registado.</span>}{createRisk.error && <span role="alert" className="text-[11px] text-rose-700">Não foi possível registar o risco.</span>}</div>
              {risks.data?.length ? <><div className="mt-3 grid gap-2 sm:grid-cols-4"><div className="rounded bg-[#f8fafc] px-2 py-1 text-[10px] text-slate-600">Exposição total<strong className="ml-1 text-[#102a43]">{riskSummary.totalExposure}</strong></div><div className="rounded bg-[#f8fafc] px-2 py-1 text-[10px] text-slate-600">Máxima<strong className="ml-1 text-[#102a43]">{riskSummary.maximumExposure}</strong></div><div className="rounded bg-rose-50 px-2 py-1 text-[10px] text-rose-700">Críticos<strong className="ml-1">{riskSummary.critical}</strong></div><div className="rounded bg-amber-50 px-2 py-1 text-[10px] text-amber-700">Altos/moderados<strong className="ml-1">{riskSummary.high + riskSummary.moderate}</strong></div></div><div className="mt-2 space-y-1">{risks.data.map((risk) => <div key={risk.id} className="flex flex-wrap items-center justify-between rounded bg-[#f8fafc] px-2 py-1 text-[11px]"><span className="font-medium">{risk.title}</span><span>Exposição {risk.exposure} · {risk.exposure >= 20 ? "Crítico" : risk.exposure >= 12 ? "Alto" : risk.exposure >= 6 ? "Moderado" : "Baixo"} · {risk.response === "REDUZIR" ? "Reduzir" : risk.response === "EVITAR" ? "Evitar" : risk.response === "TRANSFERIR" ? "Transferir" : "Aceitar"}</span></div>)}</div></> : <p className="mt-2 text-[11px] text-slate-500">Ainda não existem riscos registados para este estudo.</p>}
            </div>
            <div className="rounded border border-[#dbe5f1] bg-white p-3"><p className="text-xs font-semibold text-[#102a43]">Valuation por fluxo de caixa descontado</p><div className="mt-2 flex flex-wrap items-end gap-2"><label className="text-[11px] text-slate-600">Crescimento terminal<input aria-label="Taxa de crescimento terminal" type="number" step="0.01" min="0" max="0.99" value={terminalGrowthRate} onChange={(event) => setTerminalGrowthRate(event.target.value)} className="ml-1 h-8 w-24 rounded border border-[#dbe5f1] px-2 text-xs" /></label>{valuation.data && <div className="text-[11px] text-slate-600">Valor estimado <strong className="text-[#102a43]">{valuation.data.estimatedValue.toLocaleString("pt-PT", { maximumFractionDigits: 0 })}</strong> · Valor terminal actualizado <strong className="text-[#102a43]">{valuation.data.presentValueOfTerminal.toLocaleString("pt-PT", { maximumFractionDigits: 0 })}</strong></div>}</div><p className="mt-1 text-[11px] text-slate-500">A taxa terminal tem de ser inferior à taxa de desconto.</p></div>
            <div className="rounded border border-[#dbe5f1] bg-white p-3"><p className="text-xs font-semibold text-[#102a43]">Análise de sensibilidade</p><p className="mt-1 text-[11px] text-slate-500">Varia o custo do capital em ±2 pontos percentuais e os fluxos em ±10%.</p>{sensitivity.data?.length ? <div className="mt-2 grid grid-cols-3 gap-1 text-[10px]">{sensitivity.data.map((point) => <div key={`${point.rateDelta}-${point.cashFlowDelta}`} className={`rounded px-2 py-1 ${point.decision === "PROSSEGUIR" ? "bg-emerald-50 text-emerald-800" : point.decision === "REJEITAR" ? "bg-rose-50 text-rose-800" : "bg-amber-50 text-amber-800"}`}>Taxa {(point.rateDelta * 100).toFixed(0)}% · Fluxos {(point.cashFlowDelta * 100).toFixed(0)}%<br /><strong>VPL {point.npv.toLocaleString("pt-PT", { maximumFractionDigits: 0 })}</strong></div>)}</div> : <p className="mt-2 text-[11px] text-slate-500">Preencha as premissas para calcular a sensibilidade.</p>}</div>
            <div className="flex flex-wrap items-center justify-between gap-2 rounded border border-[#dbe5f1] bg-[#f8fafc] p-3"><div><p className="text-xs font-semibold text-[#102a43]">Relatório do estudo</p><p className="text-[11px] text-slate-500">Gera um PDF com premissas, resultados, riscos e decisão.</p></div><Button type="button" variant="outline" disabled={generateReport.isPending || !activeCompanyId || !organizationId || !selectedStudyId} onClick={() => { if (activeCompanyId && organizationId && selectedStudyId) generateReport.mutate({ organizationId, companyId: activeCompanyId, studyId: selectedStudyId }); }}>{generateReport.isPending ? "A gerar…" : "Gerar relatório PDF"}</Button>{generateReport.data?.url && <a className="text-xs font-medium text-[#1267d6] underline" href={generateReport.data.url} download={generateReport.data.filename}>Descarregar relatório</a>}{generateReport.error && <span role="alert" className="text-[11px] text-rose-700">Não foi possível gerar o relatório.</span>}</div>
            <div className="rounded border border-[#dbe5f1] bg-[#fffdf6] p-3">
              <div className="flex items-center gap-2"><ShieldCheck className="h-4 w-4 text-[#477514]" /><p className="text-xs font-semibold text-[#102a43]">Decisão humana do investimento</p></div>
              <p className="mt-1 text-[11px] text-slate-500">A decisão é registada somente depois de existir uma versão aprovada e exige fundamentação.</p>
              <div className="mt-3 flex flex-wrap items-end gap-2"><select aria-label="Decisão do investimento" value={decisionChoice} onChange={(event) => setDecisionChoice(event.target.value as typeof decisionChoice)} className="h-9 rounded-md border border-[#dbe5f1] bg-white px-2 text-xs"><option value="APROVAR">Aprovar</option><option value="REJEITAR">Rejeitar</option><option value="PEDIR_REVISAO">Pedir revisão</option></select><Input aria-label="Fundamentação da decisão" placeholder="Fundamentação obrigatória" value={decisionJustification} onChange={(event) => setDecisionJustification(event.target.value)} className="min-w-[260px] flex-1" /><Button type="button" variant="outline" disabled={submitDecision.isPending || !decisionJustification.trim() || !versions.data?.some((version) => version.status === "APPROVED")} onClick={() => { const approved = versions.data?.find((version) => version.status === "APPROVED"); if (activeCompanyId && organizationId && selectedStudyId && approved) submitDecision.mutate({ organizationId, companyId: activeCompanyId, studyId: selectedStudyId, versionId: approved.id, decision: decisionChoice, justification: decisionJustification }); }}>{submitDecision.isPending ? "A registar…" : "Registar decisão"}</Button></div>
              {decisions.data?.length ? <div className="mt-3 space-y-1">{decisions.data.map((decision) => <div key={decision.id} className="flex flex-wrap items-center justify-between rounded bg-white px-2 py-1 text-[11px]"><span>{decision.decision === "APROVAR" ? "Aprovado" : decision.decision === "REJEITAR" ? "Rejeitado" : "Revisão pedida"}</span><span>{decision.justification}</span></div>)}</div> : <p className="mt-2 text-[11px] text-slate-500">Ainda não existe uma decisão humana registada.</p>}
              {submitDecision.error && <p role="alert" className="mt-2 text-[11px] text-rose-700">A decisão exige uma versão aprovada e fundamentação.</p>}
            </div>
                        <div className="rounded border border-[#dbe5f1] bg-white p-3"><div className="flex items-center gap-2"><FlaskConical className="h-4 w-4 text-[#1267d6]" /><p className="text-xs font-semibold text-[#102a43]">Premissas financeiras</p></div><p className="mt-1 text-[11px] text-slate-500">Cada premissa conserva valor, unidade, período, fonte e observação para permitir revisão posterior.</p><div className="mt-2 grid gap-2 md:grid-cols-4"><Input aria-label="Nome da premissa" placeholder="Nome da premissa" value={assumptionName} onChange={(event) => setAssumptionName(event.target.value)} /><Input aria-label="Valor da premissa" placeholder="Valor" value={assumptionValue} onChange={(event) => setAssumptionValue(event.target.value)} /><Input aria-label="Unidade da premissa" placeholder="Unidade" value={assumptionUnit} onChange={(event) => setAssumptionUnit(event.target.value)} /><Input aria-label="Fonte da premissa" placeholder="Fonte" value={assumptionSource} onChange={(event) => setAssumptionSource(event.target.value)} /></div><div className="mt-2 grid gap-2 md:grid-cols-3"><Input aria-label="Ano inicial da premissa" type="number" value={assumptionStartYear} onChange={(event) => setAssumptionStartYear(event.target.value)} /><Input aria-label="Ano final da premissa" type="number" value={assumptionEndYear} onChange={(event) => setAssumptionEndYear(event.target.value)} /><Input aria-label="Observação da premissa" placeholder="Observação" value={assumptionNotes} onChange={(event) => setAssumptionNotes(event.target.value)} /></div><div className="mt-2 flex items-center gap-2"><Button type="button" variant="outline" disabled={createAssumption.isPending || !selectedStudyId || !organizationId || !assumptionName.trim() || !assumptionValue.trim()} onClick={() => { if (selectedStudyId && organizationId && assumptionName.trim() && assumptionValue.trim()) createAssumption.mutate({ organizationId, companyId: activeCompanyId, studyId: selectedStudyId, name: assumptionName, value: assumptionValue, unit: assumptionUnit || "unidade", startYear: Number(assumptionStartYear), endYear: Number(assumptionEndYear), source: assumptionSource || undefined, notes: assumptionNotes || undefined, dataOrigin: "MANUAL" }); }}>Guardar premissa</Button>{createAssumption.isSuccess && <span className="text-[11px] text-emerald-700">Premissa guardada.</span>}{createAssumption.error && <span role="alert" className="text-[11px] text-rose-700">Não foi possível guardar a premissa.</span>}</div>{assumptions.data?.length ? <div className="mt-2 space-y-1">{assumptions.data.map((assumption) => <div key={assumption.id} className="flex flex-wrap justify-between rounded bg-[#f8fafc] px-2 py-1 text-[11px]"><span><strong>{assumption.name}</strong> · {assumption.value} {assumption.unit}</span><span>{assumption.startYear}–{assumption.endYear} · {assumption.source ?? "Fonte não indicada"}</span></div>)}</div> : <p className="mt-2 text-[11px] text-slate-500">Ainda não existem premissas adicionais registadas.</p>}</div>
            <div className="rounded border border-[#dbe5f1] bg-white p-3"><div className="flex items-center gap-2"><FileText className="h-4 w-4 text-[#1267d6]" /><p className="text-xs font-semibold text-[#102a43]">Indicadores complementares</p></div>
{extendedIndicators.data ? <div className="mt-2 grid gap-2 sm:grid-cols-3"><div className="rounded bg-[#f8fafc] p-2 text-[10px] text-slate-600">Payback descontado<strong className="ml-1 text-[#102a43]">{extendedIndicators.data.discountedPaybackMonths == null ? "—" : `${extendedIndicators.data.discountedPaybackMonths.toFixed(1)} períodos`}</strong></div><div className="rounded bg-[#f8fafc] p-2 text-[10px] text-slate-600">Índice de rentabilidade<strong className="ml-1 text-[#102a43]">{extendedIndicators.data.profitabilityIndex.toFixed(2)}</strong></div><div className="rounded bg-[#f8fafc] p-2 text-[10px] text-slate-600">DSCR<strong className="ml-1 text-[#102a43]">{extendedIndicators.data.dscr == null ? "—" : extendedIndicators.data.dscr.toFixed(2)}</strong></div><div className="rounded bg-[#f8fafc] p-2 text-[10px] text-slate-600">Ponto de equilíbrio financeiro<strong className="ml-1 text-[#102a43]">{extendedIndicators.data.breakEvenFinancial == null ? "—" : `${(extendedIndicators.data.breakEvenFinancial * 100).toFixed(1)}%`}</strong></div><div className="rounded bg-[#f8fafc] p-2 text-[10px] text-slate-600">Ponto de equilíbrio em unidades<strong className="ml-1 text-[#102a43]">{extendedIndicators.data.breakEvenUnits == null ? "—" : extendedIndicators.data.breakEvenUnits.toFixed(1)}</strong></div><div className="rounded bg-[#f8fafc] p-2 text-[10px] text-slate-600">Margem EBITDA<strong className="ml-1 text-[#102a43]">{extendedIndicators.data.ebitdaMargin == null ? "—" : `${(extendedIndicators.data.ebitdaMargin * 100).toFixed(1)}%`}</strong></div></div> : <p className="mt-2 text-[11px] text-slate-500">Preencha premissas válidas para calcular os indicadores complementares.</p>}</div>
            <div className="rounded border border-[#dbe5f1] bg-white p-3"><div className="flex items-center gap-2"><FileText className="h-4 w-4 text-[#1267d6]" /><p className="text-xs font-semibold text-[#102a43]">Documentos do estudo</p></div><p className="mt-1 text-[11px] text-slate-500">Registe o ficheiro protegido já carregado no armazenamento do projecto. A extracção por IA permanece sugestão e exige validação humana.</p><div className="mt-2 grid gap-2 md:grid-cols-4"><Input aria-label="Nome do documento" placeholder="Nome do ficheiro" value={documentFilename} onChange={(event) => setDocumentFilename(event.target.value)} /><Input aria-label="Chave protegida do documento" placeholder="Chave de armazenamento" value={documentStorageKey} onChange={(event) => setDocumentStorageKey(event.target.value)} /><select aria-label="Categoria do documento" value={documentCategory} onChange={(event) => setDocumentCategory(event.target.value)} className="h-9 rounded-md border border-[#dbe5f1] bg-white px-2 text-xs"><option value="BALANCO">Balanço</option><option value="DRE">Demonstração de resultados</option><option value="FLUXO_CAIXA">Fluxo de caixa</option><option value="ORCAMENTO">Orçamento</option><option value="OUTRO">Outro documento</option></select><Input aria-label="Tamanho do documento" type="number" min="1" value={documentSize} onChange={(event) => setDocumentSize(event.target.value)} placeholder="Tamanho em bytes" /></div><div className="mt-2 flex flex-wrap items-center gap-2"><Button type="button" variant="outline" disabled={addDocument.isPending || !selectedStudyId || !organizationId || !documentFilename.trim() || !documentStorageKey.trim()} onClick={() => { if (selectedStudyId && organizationId && documentFilename.trim() && documentStorageKey.trim()) addDocument.mutate({ organizationId, companyId: activeCompanyId, studyId: selectedStudyId, filename: documentFilename, mimeType: documentMimeType, size: Number(documentSize) || 1, storageKey: documentStorageKey, category: documentCategory }); }}>Registar documento</Button>{addDocument.isSuccess && <span className="text-[11px] text-emerald-700">Documento registado.</span>}{addDocument.error && <span role="alert" className="text-[11px] text-rose-700">Não foi possível registar o documento.</span>}</div>{documents.data?.length ? <div className="mt-3 space-y-1">{documents.data.map((document) => <div key={document.id} className="flex flex-wrap items-center justify-between gap-2 rounded bg-[#f8fafc] px-2 py-1 text-[11px]"><span><strong>{document.filename}</strong> · {document.category} · {document.extractionStatus === "VALIDADO" ? "Validado" : document.extractionStatus === "EXTRAIDO" ? "Extraído — por validar" : document.extractionStatus === "EM_REVISAO" ? "Em revisão" : document.extractionStatus === "REJEITADO" ? "Rejeitado" : "Pendente"}</span><span className="flex items-center gap-2">{document.downloadUrl && <a className="text-[#1267d6] underline" href={document.downloadUrl} download={document.filename}>Descarregar</a>}{document.extractionStatus !== "VALIDADO" && <Button type="button" size="sm" variant="outline" disabled={reviewDocument.isPending} onClick={() => reviewDocument.mutate({ organizationId: organizationId ?? 0, studyId: selectedStudyId ?? 0, documentId: document.id, status: "VALIDADO", notes: "Validado pelo utilizador responsável." })}>Validar</Button>}</span></div>)}</div> : <p className="mt-2 text-[11px] text-slate-500">Ainda não existem documentos associados ao estudo.</p>}</div>
            <div className="grid gap-3 md:grid-cols-2"><div className="rounded border border-[#dbe5f1] bg-white p-3"><p className="text-xs font-semibold text-[#102a43]">Alertas do estudo</p>{alerts.data?.length ? <div className="mt-2 space-y-1">{alerts.data.map((alert) => <div key={alert.id} className={`rounded px-2 py-1 text-[11px] ${alert.severity === "CRITICO" ? "bg-rose-50 text-rose-800" : alert.severity === "ATENCAO" ? "bg-amber-50 text-amber-800" : "bg-emerald-50 text-emerald-800"}`}><strong>{alert.title}</strong><span className="ml-1">{alert.description}</span></div>)}</div> : <p className="mt-2 text-[11px] text-slate-500">Não existem alertas activos para este estudo.</p>}</div><div className="rounded border border-[#dbe5f1] bg-white p-3"><p className="text-xs font-semibold text-[#102a43]">Checklist de validação</p>{validations.data?.length ? <div className="mt-2 space-y-1">{validations.data.map((validation) => <div key={validation.id} className="flex items-center justify-between rounded bg-[#f8fafc] px-2 py-1 text-[11px]"><span>{validation.message}</span><Badge variant="outline">{validation.status === "VALIDADO" ? "Validado" : validation.status === "BLOQUEADO" ? "Bloqueado" : "Pendente"}</Badge></div>)}</div> : <p className="mt-2 text-[11px] text-slate-500">O checklist será preenchido à medida que os dados forem validados.</p>}</div></div><div className="rounded border border-[#dbe5f1] bg-white p-3"><p className="text-xs font-semibold text-[#102a43]">Projecções persistidas</p>{projections.data?.length ? <p className="mt-1 text-[11px] text-slate-500">{projections.data.length} valor{projections.data.length === 1 ? "" : "es"} projectado{projections.data.length === 1 ? "" : "s"} com fórmula e hash de origem.</p> : <p className="mt-1 text-[11px] text-slate-500">Ainda não existem projecções persistidas para este estudo.</p>}</div>
            {feasibility.data?.result ? <div className="grid gap-3 md:grid-cols-4">
              <div className="rounded border border-[#dbe5f1] bg-white p-3"><p className="text-[11px] text-slate-500">Valor presente líquido</p><p className="mt-1 text-lg font-semibold text-[#102a43]">{feasibility.data.result.npv.toLocaleString("pt-PT", { maximumFractionDigits: 2 })} {feasibility.data.input?.currency}</p></div>
              <div className="rounded border border-[#dbe5f1] bg-white p-3"><p className="text-[11px] text-slate-500">Taxa interna de rentabilidade</p><p className="mt-1 text-lg font-semibold text-[#102a43]">{feasibility.data.result.irr === null ? "—" : `${(feasibility.data.result.irr * 100).toFixed(2)}%`}</p></div>
              <div className="rounded border border-[#dbe5f1] bg-white p-3"><p className="text-[11px] text-slate-500">Prazo de retorno</p><p className="mt-1 text-lg font-semibold text-[#102a43]">{feasibility.data.result.paybackMonths === null ? "Não recuperado" : `${feasibility.data.result.paybackMonths.toFixed(1)} períodos`}</p></div>
              <div className="rounded border border-[#dbe5f1] bg-white p-3"><p className="text-[11px] text-slate-500">Decisão analítica</p><p className={`mt-1 text-lg font-semibold ${feasibility.data.result.decision === "PROSSEGUIR" ? "text-emerald-700" : feasibility.data.result.decision === "REJEITAR" ? "text-rose-700" : "text-amber-700"}`}>{feasibility.data.result.decision === "PROSSEGUIR" ? "Prosseguir" : feasibility.data.result.decision === "REJEITAR" ? "Rejeitar" : "Rever"}</p></div>
            </div> : <p className="text-xs text-slate-500">Ainda não existe resultado calculado para este estudo.</p>}
          </>}
        </CardContent>
      </Card>
    </div>
  );
}
